// Advantage — Bonzo new lead -> GHL contact upsert. FILL the REPLACE_* placeholders.
const LOCATION_ID = 'REPLACE_GHL_LOCATION_ID';
const CF = {
  external_lead_id:    'REPLACE_FIELD_ID_external_lead_id', // Bonzo lead id (clean value)
  lead_notes:          'REPLACE_FIELD_ID_lead_notes',
  custom_introduction: 'REPLACE_FIELD_ID_custom_introduction',
};
const body = $json.body || $json || {};
const g = (k) => (body[k] != null ? String(body[k]).trim() : '');
const leadid    = g('leadid') || g('id') || g('lead_id');
const firstName = g('firstname') || g('first_name');
const lastName  = g('lastname') || g('last_name');
const email     = g('email');
let phone = (g('phone') || g('mobile')).replace(/[^\d+]/g,'');
if (phone && !phone.startsWith('+')) { if (phone.length===10) phone='+1'+phone; else if (phone.length===11 && phone.startsWith('1')) phone='+'+phone; }
const intro = "So " + (firstName || 'there') + ", it's just <AGENT> from Advantage Lending. You uhh reached out about <PRODUCT>, right?";
const customFields = [];
if (leadid) customFields.push({ id: CF.external_lead_id, value: leadid });
customFields.push({ id: CF.custom_introduction, value: intro });
const contact = { locationId: LOCATION_ID, firstName: firstName||undefined, lastName: lastName||undefined,
  name: (firstName+' '+lastName).trim()||undefined, source: 'Bonzo', customFields };
if (phone) contact.phone = phone;
if (email && email.indexOf('@')>-1) contact.email = email;
return [{ json: { ready: !!(leadid && (phone||email)), reason: !leadid ? 'Missing lead id' : (!(phone||email)?'No phone/email':null), leadid, contact, raw: body } }];
